use vstd::prelude::*;

verus! {

spec fn map_char(c: char) -> char {
    if c == ',' { ' ' } else { c }
}

spec fn mapped_prefix(s: Seq<char>, n: nat) -> Seq<char>
    recommends n <= s.len(),
    decreases n,
{
    if n == 0 {
        Seq::<char>::empty()
    } else {
        mapped_prefix(s, (n - 1) as nat).push(map_char(s[(n - 1) as int]))
    }
}

fn solve(s: Vec<char>) -> (out: Vec<char>)
    requires
        s@.len() >= 19,
    ensures
        out@.len() == 20,
        // first 19 chars are mapped with ',' -> ' ' and otherwise unchanged
        out@.subrange(0, 19) == mapped_prefix(s@, 19),
        // final newline
        out@[19] == '\n',
{
    // Input is assumed to have length 19 as per the problem statement.
    let mut result = Vec::with_capacity(20);

    for &ch in s.iter().take(19)
        invariant
            result@.len() <= 19,
            result@ == mapped_prefix(s@, result@.len() as nat),
        decreases 19 - result@.len(),
    {
        if ch == ',' {
            result.push(' ');
        } else {
            result.push(ch);
        }
    }

    result.push('\n');
    result
}

} // verus!

